import json
from lib import *
R = J('r130'); cm = R['cmds']; ac = R['acl']; tab = R['tab']; lp = R['loop']; lw = R['loop_w']; ty = R['types']
KV = lambda items, hl=(): {'items': items, 'hl': list(hl)}
def fl(nodes, cur=(), done=(), mark=()): return {'nodes': nodes, 'cur': list(cur), 'done': list(done), 'mark': list(mark)}
def tl(lines, cur=(), mark=()): return {'lines': lines, 'cur': list(cur), 'mark': list(mark)}
def bars(items, mx, cur=(), mark=(), done=()): return {'items': items, 'max': mx, 'cur': list(cur), 'mark': list(mark), 'done': list(done)}
allowed = [k for k, v in cm.items() if v == 'OK']; denied = [k for k, v in cm.items() if v != 'OK']
steps = [
    step(f"脚本能看到的全局:{len(R['globals'])} 个,包括 redis、cjson、cmsgpack、struct、bit、os、string、table、math 等。io、package、debug、require、dofile、loadfile、print 读取时直接报错 nonexistent global;os 表里只有 {', '.join(R['os_keys'])}(没有 execute)。", t=tl(['os 里有: ' + ', '.join(R['os_keys']), 'io / package / debug → 不存在', 'require / dofile / loadfile / print → 不存在', 'load / loadstring → function(仍在沙箱内)']), kv=KV([['os', ', '.join(R['os_keys'])]], ['os'])),
    step("全局环境是只读的:x = 1、_G.y = 1、string.foo = 1、redis.foo = 1、os = nil、setmetatable(_G, {}) 全部报 Attempt to modify a readonly table。局部变量不受限。loadstring(\"x = 1\")() 同样被拒,loadstring 没有绕开沙箱。", t=tl([f"{k:<30} {v}" for k, v in R['mod'].items()], mark=[0, 1, 2, 3, 5, 6], cur=[4]), kv=KV([['全局', '只读']], ['全局'])),
    step(f"脚本里调用命令:{', '.join(allowed)} 可以;{'、'.join(x.split()[0] for x in denied)} 等 {len(denied)} 条被拒:This Redis command is not allowed from script。注意 KEYS、FLUSHDB 在允许之列——脚本能做的破坏和调用者一样大。", t=tl([f"{k:<24} {'允许' if v == 'OK' else '不允许'}" for k, v in cm.items()], mark=[i for i, v in enumerate(cm.values()) if v != 'OK'], cur=[i for i, v in enumerate(cm.values()) if v == 'OK']), kv=KV([['不允许', len(denied)], ['允许', len(allowed)]], ['不允许'])),
    step("ACL 对脚本内每一次 redis.call 都单独检查:luser 只有 ~app:* +get +set +eval。脚本里 GET app:1 → nil(通过);GET other:1 → ACL failure … No permissions to access a key;DEL / KEYS → ACL failure … has no permissions to run the '…' command;没在 KEYS 里声明的 app:2 只要符合 ACL 模式也能 SET。EVAL_RO 里 SET → Write commands are not allowed from read-only scripts。", t=tl([f"{k:<28} {v[:70]}" for k, v in ac.items()], cur=[0, 4], mark=[1, 2, 3, 6]), kv=KV([['+eval', '不等于「什么都能做」']], ['+eval'])),
    step(f"限制脚本要小心「漏一半」:-@scripting 把 EVAL / EVALSHA / SCRIPT / FUNCTION / FCALL 全拒;但只禁 eval、evalsha、eval_ro、evalsha_ro 四条时,SCRIPT LOAD → {tab['SCRIPT LOAD return 1'][1]},FUNCTION LOAD → {tab['FUNCTION LOAD #!lua name'][1]},FCALL → {tab['FCALL f 0'][1]}(DRYRUN 判定)。", t=tl([f"{k:<26} -@scripting:{v[0]}   只禁 4 条:{v[1]}" for k, v in tab.items()], mark=[2, 3, 4, 5]), kv=KV([['-@scripting', '全拒'], ['只禁 EVAL 四条', 'FUNCTION / FCALL 仍开']], ['只禁 EVAL 四条'])),
    step(f"死循环脚本:busy-reply-threshold 默认 {R['thr_default']} ms(测试时调成 500 ms)。另一条连接的 PING 等了约 {lp['ping_ms']:.0f} ms,然后得到 BUSY Redis is busy running a script。纯死循环可以 SCRIPT KILL → {lp['kill']},脚本报 Script killed by user。", b=bars([['另一连接 PING 的等待(ms)', lp['ping_ms'], f"{lp['ping_ms']:.0f}"], ['busy-reply-threshold(ms,测试值)', 500, '500']], 600, mark=[0], done=[1]), kv=KV([['BUSY 之前', '其他客户端都在排队'], ['SCRIPT KILL', lp['kill']]], ['BUSY 之前'])),
    step(f"如果脚本已经写过数据再死循环:SCRIPT KILL → {lw['kill'].split(' ')[0]}(Sorry the script already executed write commands…);唯一出路是 SHUTDOWN NOSAVE(实测:进程退出,{'已退出' if not lw['alive_after_shutdown'] else '仍在'}),不保存最近的数据。", n=fl([['脚本 SET 之后死循环', ''], ['SCRIPT KILL', 'UNKILLABLE'], ['SHUTDOWN NOSAVE', '进程退出']], mark=[1], done=[2]), kv=KV([['写过数据的死循环', '只能 SHUTDOWN NOSAVE']], ['写过数据的死循环'])),
]
A = dict(
    n=130, series='redis', tags='Redis,Lua,安全,ACL,真实验证,动画演示',
    desc='Redis 8.10.2 的 Lua 沙箱实测:os 里只有 clock,io / package / require 都不存在,全局与标准库只读;脚本里 CONFIG / ACL / SUBSCRIBE / EVAL 等命令被拒但 KEYS / FLUSHDB 可以;ACL 对脚本里每次 redis.call 逐条检查;只禁 EVAL 四条会漏掉 FUNCTION / FCALL;写过数据的死循环脚本 SCRIPT KILL 不掉。',
    lead='Redis 允许客户端提交一段 Lua 脚本在服务端运行。那它能碰到什么?能不能读文件、执行系统命令、改全局环境?ACL 对脚本内部有没有效?这篇只做一件事:在本机的 8.10.2 上把沙箱的边界逐条试出来,并给出限制脚本时容易漏掉的地方。',
    facts=[('os 只有 clock', f'脚本里没有 io / package / require / dofile / print,os 只剩 {", ".join(R["os_keys"])}'), ('逐条检查', 'ACL 对脚本里的每一次 redis.call 都生效;+eval 不等于什么都能做'), ('漏一半', '只禁 eval / evalsha / eval_ro / evalsha_ro 四条时,SCRIPT LOAD / FUNCTION LOAD / FCALL 仍被允许;用 -@scripting 才是全拒')],
    body=[
        sec('脚本的环境', '', term('', blk('r130', 1)), '<p>沙箱里没有文件、进程、模块加载的入口:<code>io</code>、<code>package</code>、<code>require</code>、<code>dofile</code>、<code>loadfile</code>、<code>print</code> 读取时直接报 <code>nonexistent global</code>;<code>os</code> 只剩 <code>clock</code>。<code>load</code> / <code>loadstring</code> 还在,但它们跑在同一个沙箱里(<code>loadstring("x = 1")()</code> 同样被拒)。<code>cjson</code>、<code>cmsgpack</code>、<code>struct</code>、<code>bit</code> 可用。</p>'),
        sec('全局环境只读', '', term('', blk('r130', 2)), '<p>创建全局变量、改标准库表、改 <code>redis</code> 表、给 <code>_G</code> 设元表,全部报 <code>Attempt to modify a readonly table</code>。脚本之间不能通过全局变量互相传东西——要传就走 Redis 里的 key。</p>'),
        sec('脚本里能调用哪些命令', '', term('', blk('r130', 3)), '<p><code>CONFIG</code>、<code>ACL</code>、<code>SUBSCRIBE</code>、<code>MONITOR</code>、<code>WATCH</code>、<code>MULTI</code>、<code>EVAL</code>、<code>SAVE</code>、<code>DEBUG</code>、<code>SCRIPT</code>、<code>CLIENT</code>、<code>SLAVEOF</code> 被拒;<code>SET</code>、<code>KEYS</code>、<code>FLUSHDB</code>、<code>BLPOP</code> 可以。这是「不许改服务器状态、不许阻塞连接」的一条线,不是「不许破坏数据」的线——所以能执行 <code>EVAL</code> 的人,能做的数据破坏跟他自己直接执行命令一样多,取决于他的 ACL。(没有测 <code>SHUTDOWN</code> 等其余命令。)</p>'),
        sec('ACL 在脚本内部', '', term('', blk('r130', 4)), '<p>脚本里每次 <code>redis.call</code> 都按调用者的 ACL 检查(命令和 key 都查)。<code>redis.pcall</code> 把 ACL 失败作为错误值返回而不是终止脚本。没在 <code>KEYS</code> 里声明的 key,只要符合 ACL 的 key 模式仍然可以访问(单机下的实测)。<code>EVAL_RO</code> 里写命令被拒。</p>'),
        sec('限制脚本:别只禁 EVAL', '', term('', blk('r130', 5)), '<p>脚本相关的命令有 21 条(见上面 <code>@scripting</code> 的完整列表)。只禁 <code>eval</code> 系列四条,<code>FUNCTION LOAD</code> 后 <code>FCALL</code> 仍然能跑 Lua。要禁就用 <code>-@scripting</code>,然后 <code>ACL DRYRUN</code> 验一遍。</p>'),
        sec('死循环与 SCRIPT KILL', '', term('', blk('r130', 6)), '<p>脚本运行时服务器是单线程忙碌的,其它连接的命令要等。超过 <code>busy-reply-threshold</code>(默认 5000 ms;别名 <code>lua-time-limit</code>)后,其它连接得到 <code>BUSY</code>,只能 <code>SCRIPT KILL</code> 或 <code>SHUTDOWN NOSAVE</code>。脚本一旦写过数据,<code>SCRIPT KILL</code> 返回 <code>UNKILLABLE</code>,只剩 <code>SHUTDOWN NOSAVE</code>。所以没有写权限的用户跑死循环,伤害是可恢复的;有写权限的,只能停服务。</p>'),
        sec('分步演示:沙箱的边界', '', demo('Lua 安全边界', [('t', 'term', '试验结果'), ('n', 'flow', '过程'), ('b', 'bars', '等待时间'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_R + '。busy-reply-threshold 在测试里调成 500 ms;SHUTDOWN NOSAVE 只在我自己的临时实例上执行', '没有验证:沙箱逃逸类漏洞(这里只测了设计边界,不代表没有漏洞;跟进版本公告与升级)、脚本内存/递归上限、cjson / cmsgpack 自身的输入限制、集群模式下未声明 key 的行为、SCRIPT DEBUG、脚本在从库与 AOF 中的复制语义(见第 131 篇之外)'],
)
